    check(!(b?.warnings || []).length, "Notion returned setup warnings");
    switch (s.phase) {
      case "parent":
        return collect(s, b, s.config.notionParentPageId, "parent") || rootFound(s);
      case "create_root":
        check(validId(b?.id) && key(b.parent?.page_id) === key(s.config.notionParentPageId), "Unexpected created page");
        s.rootPageId = b.id;
        s.created.page = true;
        return rootContents(s);
      case "root":
        return collect(s, b, s.rootPageId, "root") || databaseFound(s);
      case "create_database":
        check(validId(b?.id) && key(b.parent?.page_id) === key(s.rootPageId), "Unexpected created database");
        s.databaseId = b.id;
        s.created.database = true;
        return request(s, "GET", "/databases/" + s.databaseId, null, "database");
      case "database":
        return source(s, b);
      case "schema":
        return schema(s, b);
      case "patch_schema":
        s.patched = true;
        return request(s, "GET", "/data_sources/" + s.dataSourceId, null, "schema");
      case "existing_database":
        check(b?.object === "database" && key(b.id) === key(s.databaseId) && !b.archived && !b.in_trash, "Unexpected existing database");
        s.rootPageId = b.parent?.page_id;
        check(validId(s.rootPageId), "The catalog database must be inside a page");
        if (validId(s.config.documentationRootPageId)) check(key(s.rootPageId) === key(s.config.documentationRootPageId), "Configured root does not contain this database");
        return complete(s);
      case "guide":
        return collect(s, b, s.rootPageId, "guide") || ensureGuide(s);
      case "create_guide":
        check(validId(b?.id) && key(b.parent?.page_id) === key(s.rootPageId), "Unexpected setup guide");
        s.guidePageId = b.id;
        s.created.guide = true;
        return complete(s);
      default:
        throw Error("Unknown setup phase " + s.phase);
    }
  }
  return {initialize,advance};
})();

return [{json:Setup.advance($("Keep setup state").last().json,$input.first().json)}];
